async def act(page):
    """
    From the current Orders grid state, attempt to cancel order 305 by:
    - Dismissing the visible popup.
    - Increasing the 'View' (rows per page) to 200 so the order is more likely visible.
    - Using the Search textbox to narrow to 305 (try padded and short forms).
    - Finding the matching row and clicking its checkbox.
    - Using the scoped bulk-action combobox (Select Visible area) to choose 'Cancel' via select_option(label="Cancel").
    - Clicking the scoped Submit button and confirming any OK/Yes dialog.

    Notes about KB helpers: none of the provided knowledge-base helpers provide order-management (cancel) actions; they focus on the dashboard and CSV exports.
    """
    import asyncio

    async def exists(locator):
        try:
            return await locator.count() > 0
        except Exception:
            return False

    # 0) Dismiss the visible popup if possible using accessible button names, then press Escape.
    for name in ("×", "Close", "OK", "Ok", "Dismiss"):
        try:
            btn = page.get_by_role("button", name=name)
            if await exists(btn):
                try:
                    await btn.first.click()
                    await page.wait_for_timeout(300)
                except Exception:
                    pass
        except Exception:
            pass

    try:
        await page.keyboard.press("Escape")
        await page.wait_for_timeout(200)
    except Exception:
        pass

    # 1) Increase rows-per-page to 200 so the order is more likely to be visible on the current page.
    # Find a combobox that contains options like "20" and "200"
    view_combo = None
    comboboxes = page.get_by_role("combobox")
    for i in range(0, await comboboxes.count()):
        c = comboboxes.nth(i)
        try:
            texts = await c.all_inner_texts()
            flat = " ".join([t or "" for t in texts])
            # identify the pagination combobox by the presence of typical pagination choices
            if "20" in flat and "200" in flat:
                view_combo = c
                break
        except Exception:
            continue

    if view_combo is not None:
        try:
            # select 200 rows per page
            await view_combo.select_option(label="200")
            # allow grid to refresh after changing page size
            await page.wait_for_timeout(900)
        except Exception:
            # ignore and continue; we'll still attempt search and scanning
            await page.wait_for_timeout(500)

    # 2) Use the Search group textbox to filter for the order. Try both padded and short forms.
    search_group = page.get_by_role("group", name="Search")
    if await exists(search_group):
        search_box = search_group.get_by_role("textbox")
        if await exists(search_box):
            for q in ("000000305", "305"):
                try:
                    await search_box.fill(q)
                    await search_box.press("Enter")
                    await page.wait_for_timeout(900)
                except Exception:
                    # continue with next query
                    pass

    # 3) Locate the table row that contains the order increment id (try both padded and short forms)
    tables = page.get_by_role("table")
    target_row = None
    for candidate in ("000000305", "305"):
        for i in range(0, await tables.count()):
            tbl = tables.nth(i)
            try:
                if await tbl.get_by_text(candidate).count() > 0:
                    rows = tbl.get_by_role("row").filter(has=tbl.get_by_text(candidate))
                    if await rows.count() > 0:
                        target_row = rows.first
                        break
            except Exception:
                continue
        if target_row:
            break

    # brief retry if not yet found
    if not target_row:
        await page.wait_for_timeout(800)
        tables = page.get_by_role("table")
        for candidate in ("000000305", "305"):
            for i in range(0, await tables.count()):
                tbl = tables.nth(i)
                try:
                    if await tbl.get_by_text(candidate).count() > 0:
                        rows = tbl.get_by_role("row").filter(has=tbl.get_by_text(candidate))
                        if await rows.count() > 0:
                            target_row = rows.first
                            break
                except Exception:
                    continue
            if target_row:
                break

    if not target_row:
        raise RuntimeError("Order 305 not found in the orders grid after search and page-size adjustment.")

    # 4) Click the checkbox in that row
    checkbox = target_row.get_by_role("checkbox")
    if await exists(checkbox):
        await checkbox.first.click()
        await page.wait_for_timeout(300)
    else:
        raise RuntimeError("Checkbox for order 305's row not found.")

    # 5) Locate the bulk-action controls scoped under the table row that contains 'Select Visible'
    control_table = page.get_by_role("table").filter(has=page.get_by_text("Select Visible"))
    if not await exists(control_table):
        # fallback: find any table containing a combobox and a Submit button
        control_table = None
        for i in range(0, await tables.count()):
            tbl = tables.nth(i)
            try:
                if await tbl.get_by_role("combobox").count() > 0 and await tbl.get_by_role("button", name="Submit").count() > 0:
                    control_table = tbl
                    break
            except Exception:
                continue
        if control_table is None:
            raise RuntimeError("Bulk action controls not found on the page.")
    else:
        control_table = control_table.first

    action_group = control_table.get_by_role("group")

    # 6) Select the 'Cancel' option using select_option(label=...)
    combo = action_group.get_by_role("combobox")
    if not await exists(combo):
        raise RuntimeError("Actions combobox not found in the bulk actions area.")

    try:
        await combo.first.select_option(label="Cancel")
        await page.wait_for_timeout(200)
    except Exception:
        # fallback: read option texts and select one that contains 'cancel'
        try:
            labels = await combo.first.all_inner_texts()
            chosen = None
            for l in labels:
                if l and 'cancel' in l.lower():
                    chosen = l
                    break
            if chosen:
                await combo.first.select_option(label=chosen)
                await page.wait_for_timeout(200)
            else:
                raise RuntimeError("'Cancel' option not available in actions combobox.")
        except Exception as e:
            raise RuntimeError(f"Failed to select 'Cancel' in actions combobox: {e}")

    # 7) Click the scoped Submit button and confirm any dialog
    submit_btn = action_group.get_by_role("button", name="Submit")
    if await exists(submit_btn):
        await submit_btn.first.click()
        await page.wait_for_timeout(900)
        ok_btn = page.get_by_role("button", name="OK")
        yes_btn = page.get_by_role("button", name="Yes")
        if await exists(ok_btn):
            await ok_btn.first.click()
            await page.wait_for_timeout(300)
            return
        if await exists(yes_btn):
            await yes_btn.first.click()
            await page.wait_for_timeout(300)
            return
        # assume success if no confirmation dialog found
        return

    raise RuntimeError("Submit button for bulk action not found.")

